"""Export the SQLite schema from the same metadata used by the ORM."""

from __future__ import annotations

import argparse
from pathlib import Path

from sqlalchemy.dialects import sqlite
from sqlalchemy.schema import CreateColumn, CreateIndex

from app.models import Base

SCHEMA_PATH = Path(__file__).resolve().parents[2] / "database" / "schema.sql"


def render_schema() -> str:
    dialect = sqlite.dialect()
    compiler = dialect.ddl_compiler(dialect, None)
    sections = [
        "-- Generated by: cd backend && python -m scripts.export_schema",
        "-- Source of truth: app.models.Base.metadata. Intended for an empty SQLite database.",
        "PRAGMA foreign_keys = ON;",
        "BEGIN TRANSACTION;",
    ]
    for table in Base.metadata.sorted_tables:
        definitions = [compiler.process(CreateColumn(column)) for column in table.columns]
        # Explicit ordering keeps the checked-in script stable across Python processes.
        constraints = [table.primary_key] + sorted(
            (constraint for constraint in table.constraints if constraint is not table.primary_key),
            key=lambda constraint: str(constraint.name),
        )
        definitions.extend(compiler.process(constraint) for constraint in constraints)
        body = ",\n    ".join(definitions)
        name = compiler.preparer.format_table(table)
        sections.append(f"CREATE TABLE {name} (\n    {body}\n);")
        for index in sorted(table.indexes, key=lambda item: item.name or ""):
            sections.append(str(CreateIndex(index).compile(dialect=dialect)).strip() + ";")
    sections.append("COMMIT;")
    return "\n\n".join(sections) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=SCHEMA_PATH)
    args = parser.parse_args()
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(render_schema(), encoding="utf-8")
    print(f"Exported {len(Base.metadata.tables)} tables to {args.output}")


if __name__ == "__main__":
    main()
